const extracted = $("Extract Master CV").first().json;

const parseJson = (value) => {
  if (typeof value !== "string") return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

const unwrapMasterCv = (value) => {
  let current = parseJson(value);

  for (let depth = 0; depth < 5; depth++) {
    if (!current || typeof current !== "object" || Array.isArray(current)) {
      break;
    }

    if (Array.isArray(current.projects)) {
      return current;
    }

    const next =
      current.master_cv ??
      current.cv_json ??
      current.document_data ??
      current.data ??
      current.json;

    if (next === undefined || next === current) {
      break;
    }

    current = parseJson(next);
  }

  return current;
};

const masterCv = unwrapMasterCv(extracted);

if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("The master CV file must contain a JSON object.");
}

if (!Array.isArray(masterCv.projects)) {
  throw new Error(
    "The master CV JSON could not be normalized: projects must be an array."
  );
}

const isTrue = (value) => {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value === 1;

  if (value && typeof value === "object") {
    value = value.value ?? value.name ?? value.id;
  }

  return ["true", "1", "yes", "active", "enabled"].includes(
    String(value ?? "").trim().toLowerCase()
  );
};

const seen = new Set();
const startUrls = [];

for (const item of $input.all()) {
  const row =
    item.json.fields && typeof item.json.fields === "object"
      ? item.json.fields
      : item.json;

  const url = row["Generated URL"];

  if (!isTrue(row.Active) || typeof url !== "string" || !url.trim()) {
    continue;
  }

  const normalized = url.trim();

  if (!seen.has(normalized)) {
    seen.add(normalized);
    startUrls.push({ url: normalized });
  }
}

if (startUrls.length === 0) {
  throw new Error(
    "No active Search Criteria rows contain a Generated URL."
  );
}

return [
  {
    json: {
      master_cv: masterCv,
      startUrls,
    },
  },
];

const job = $("Loop Over Jobs").item.json;
const canonical = (value) => String(value ?? "").trim().replace(/[?#].*$/, "").replace(/\/$/, "").toLowerCase();
const target = canonical(job.jobUrl);

if (!target) {
  return [{ json: {} }];
}

const exists = $input.all().some((item) => {
  const row = item.json.fields && typeof item.json.fields === "object"
    ? item.json.fields
    : item.json;
  return canonical(row.Link) === target;
});

if (exists) {
  return [{ json: {} }];
}

return [{ json: job }];

const job = $json;
const collected = $("Collect Active Start URLs").first().json;
const masterCv = collected.master_cv;

if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("master_cv must be an object.");
}

if (!Array.isArray(masterCv.projects)) {
  throw new Error("master_cv.projects must be an array.");
}

if (!Array.isArray(masterCv.work_experience)) {
  throw new Error("master_cv.work_experience must be an array.");
}

if (!Array.isArray(masterCv.skills)) {
  throw new Error("master_cv.skills must be an array.");
}

const slugify = (value) =>
  String(value ?? "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "") || "unknown";

const jobId =
  String(job.jobId ?? "").trim() || slugify(job.jobUrl);

const applicationId =
  `${slugify(job.companyName)}-${slugify(job.jobTitle)}-${slugify(jobId)}`;

return [
  {
    json: {
      test_mode: false,
      job_id: jobId,
      company_name: job.companyName,
      job_title: job.jobTitle,
      job_description: job.jobDescription,
      job_url: job.jobUrl,
      published_at: job.publishedAt,
      location: job.location,
      contract_type: job.contractType,
      application_id: applicationId,
      project_selection_count: 4,
      work_experience_selection_count: 3,
      master_cv: masterCv,
      source_job: job,
    },
  },
];

if (!$json.cv_json || typeof $json.cv_json !== "object") {
  throw new Error("CV content workflow did not return cv_json.");
}

return [{
  json: {
    ...$json,
    document_type: "cv",
    document_data: $json.cv_json,
  },
}];

const cvResult = $("Create Tailored CV Content").item.json;
const job = cvResult.source_job;

return [{
  json: {
    test_mode: false,
    job_id: cvResult.job_id,
    company_name: cvResult.company_name,
    job_title: cvResult.job_title,
    job_description: cvResult.job_description,
    job_url: cvResult.job_url,
    published_at: cvResult.published_at,
    location: cvResult.location,
    contract_type: cvResult.contract_type,
    application_id: cvResult.application_id,
    master_cv: cvResult.cv_json,
    source_job: job,
  },
}];

if (!$json.cover_letter_json || typeof $json.cover_letter_json !== "object") {
  throw new Error("Cover letter workflow did not return cover_letter_json.");
}

return [{
  json: {
    ...$json,
    document_type: "cover-letter",
    document_data: $json.cover_letter_json,
  },
}];

const cvContent = $("Create Tailored CV Content").item.json;
const job = cvContent.source_job;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const applicationId = String(cvContent.application_id ?? "application");

const dateValue = job.publishedAt
  ? String(job.publishedAt).slice(0, 10)
  : new Date().toISOString().slice(0, 10);

return [{
  json: {
    "Job ID": String(cvContent.job_id ?? ""),
    "Date": dateValue,
    "Company Name": job.companyName ?? "",
    "Title": job.jobTitle ?? "",
    "Location": job.location ?? "",
    "Job Description": job.jobDescription ?? "",
    "Contract Type": job.contractType ?? "",
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ],
    "Link": job.jobUrl ?? "",
    "Status": "New"
  }
}];
